<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Api\Concerns\HandlesDomainModules; use App\Http\Controllers\Controller; use App\Http\Requests\PricingModuleRequest; use Illuminate\Http\JsonResponse; class PricingModuleController extends Controller { use HandlesDomainModules; protected function domain(): string { return 'pricing'; } public function store(PricingModuleRequest $request, string $module): JsonResponse { $this->registry->assertDomain($this->domain(), $module); return response()->json($this->service->create($request, $module, $request->validated()), 201); } public function update(PricingModuleRequest $request, string $module, int $id): JsonResponse { $this->registry->assertDomain($this->domain(), $module); return response()->json($this->service->update($request, $module, $id, $request->validated())); } }
